import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.DT_qyuxR.js";const p=JSON.parse('{"title":"Présentation","description":"","frontmatter":{},"headers":[],"relativePath":"regles/01-presentation.md","filePath":"regles/01-presentation.md"}'),r={name:"regles/01-presentation.md"};function i(o,e,l,d,u,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h1><h2 id="le-concept" tabindex="-1">Le concept <a class="header-anchor" href="#le-concept" aria-label="Permalink to &quot;Le concept&quot;">​</a></h2><p>Carnival of the Deads se déroule lors d&#39;un <strong>bal masqué maudit</strong>. Les invités portent des masques qui leur confèrent des identités et des pouvoirs. Mais une malédiction plane sur le bal : chaque nuit, des masques se brisent, révélant ceux qui se cachent derrière.</p><p>Le jeu est joué sur <strong>Discord</strong> via un bot qui gère automatiquement les phases, les actions et les résolutions. Un joueur — l&#39;<strong>Hôte du Carnaval</strong> — pilote la partie et arbitre les situations ambiguës.</p><h2 id="les-camps" tabindex="-1">Les camps <a class="header-anchor" href="#les-camps" aria-label="Permalink to &quot;Les camps&quot;">​</a></h2><p>La partie oppose deux camps :</p><h3 id="les-vivants" tabindex="-1">Les Vivants <a class="header-anchor" href="#les-vivants" aria-label="Permalink to &quot;Les Vivants&quot;">​</a></h3><p>Les Invités qui tentent de survivre au bal. Leur objectif : <strong>éliminer tous les Revenants</strong> avant qu&#39;ils ne les emportent tous. Ils seignent leur camp entre eux, mais ne connaissent pas ceux des autres.</p><h3 id="les-revenants-le-cercle" tabindex="-1">Les Revenants (le Cercle) <a class="header-anchor" href="#les-revenants-le-cercle" aria-label="Permalink to &quot;Les Revenants (le Cercle)&quot;">​</a></h3><p>Un groupe secret d&#39;Invités possédés par l&#39;esprit du bal. Leur objectif : <strong>éliminer tous les Vivants</strong>. Ils se reconnaissent entre eux et tentent de se fondre dans la masse.</p><h3 id="distribution-des-camps" tabindex="-1">Distribution des camps <a class="header-anchor" href="#distribution-des-camps" aria-label="Permalink to &quot;Distribution des camps&quot;">​</a></h3><ul><li>À la création de la partie, le bot tire aléatoirement environ <strong>1/3 des joueurs</strong> comme Revenants (minimum 1).</li><li>Chaque joueur reçoit secrètement son camp. Seuls les Revenants savent qui sont les autres Revenants.</li><li>L&#39;Hôte du Carnaval valide la composition avant de lancer la partie.</li></ul><h2 id="le-nombre-de-joueurs" tabindex="-1">Le nombre de joueurs <a class="header-anchor" href="#le-nombre-de-joueurs" aria-label="Permalink to &quot;Le nombre de joueurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Joueurs</th><th>Revenants</th><th>Vivants</th><th>Durée estimée</th></tr></thead><tbody><tr><td>6</td><td>2</td><td>4</td><td>20-30 min</td></tr><tr><td>7</td><td>2-3</td><td>4-5</td><td>25-35 min</td></tr><tr><td>8</td><td>3</td><td>5</td><td>30-40 min</td></tr><tr><td>9</td><td>3</td><td>6</td><td>35-45 min</td></tr><tr><td>10</td><td>3-4</td><td>6-7</td><td>40-50 min</td></tr><tr><td>11</td><td>4</td><td>7</td><td>45-55 min</td></tr><tr><td>12</td><td>4</td><td>8</td><td>50-60 min</td></tr></tbody></table><h2 id="l-originalite" tabindex="-1">L&#39;originalité <a class="header-anchor" href="#l-originalite" aria-label="Permalink to &quot;L&#39;originalité&quot;">​</a></h2><p>Carnival of the Deads se distingue des autres jeux de déduction par :</p><ul><li><strong>Les PV secrets</strong> : les joueurs connaissent leurs propres PV mais pas ceux des autres. Seul le total de dégâts reçus est public.</li><li><strong>Les masques</strong> : chaque masque a des capacités uniques (Jour, Nuit) et un passif. Le choix du masque influence la stratégie.</li><li><strong>Les Revenants aléatoires</strong> : les camps sont tirés au sort, pas choisis. Personne ne sait qui est Revenant avant que les masques ne se brisent.</li><li><strong>Les zones vocales</strong> : les joueurs se déplacent entre 3 salons vocaux. Certains masques vérifient leur position.</li><li><strong>Les rumeurs</strong> : un joueur K.O. peut laisser un dernier message — une rumeur qui peut contenir des indices ou des mensonges.</li></ul><h2 id="theme" tabindex="-1">Thème <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Thème&quot;">​</a></h2><p>Le jeu s&#39;inspire du folklore des carnavals macabres. Les masques sont des créatures fantastiques — pas des Pokémon — et le ton est sombre mais festif. L&#39;Hôte du Carnaval est le narrateur, celui qui fait vivre l&#39;ambiance du bal.</p>',19)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
